var browser = new InstalledApp("Google Chrome", "chrome.lnk", "chrome", "Chrome", false, "chrome.exe");
var webApp = new InstalledApp("Mail", "mail.lnk", "chrome", "Chrome._crx_mail.Profile2", true, "chrome_proxy.exe");
Check("App names match full name ignoring case and surrounding spaces", AppNames.Resolve(" google CHROME ", [browser, webApp]) == browser);
Check("App-only configuration accepted", Configuration.Parse("""{"mappings":{"4":{"action":"application","startMenuName":"Google Chrome"}}}""").Mappings["4"].StartMenuName == "Google Chrome");
Check("App process override accepted", Configuration.Parse("""{"mappings":{"4":{"action":"application","startMenuName":"Example","process":"helper"}}}""").Mappings["4"].Process == "helper");
Reject("App lookup disallowed for command actions", """{"mappings":{"4":{"action":"command","startMenuName":"Chrome","executable":"chrome.exe"}}}""");
bool missingApp = false;
try { AppNames.Resolve("Googl Chrom", [browser, webApp]); } catch (Exception ex) { missingApp = ex.Message.Contains("Google Chrome"); }
Check("Missing app offers nearby names without silently guessing", missingApp);
bool ambiguousApp = false;
try { AppNames.Resolve("Mail", [webApp, webApp with { Launcher = "other-profile.lnk", AppId = "Chrome._crx_mail.Default" }]); } catch (Exception ex) { ambiguousApp = ex.Message.Contains("ambiguous"); }
Check("Duplicate names with different profiles are rejected", ambiguousApp);
Check("Identical catalog entries deduplicated", AppNames.Resolve("Mail", [webApp, webApp]) == webApp);
Check("Chrome app matches exact profile identity", AppNames.IdentityMatches(webApp, "Chrome._crx_mail.Profile2"));
Check("Chrome app rejects regular browser", !AppNames.IdentityMatches(webApp, "Chrome"));
Check("Chrome app rejects another profile", !AppNames.IdentityMatches(webApp, "Chrome._crx_mail.Default"));
Check("Chrome app rejects missing identity", !AppNames.IdentityMatches(webApp, ""));
Check("Applications reuse windows by default", !Configuration.Parse("""{"mappings":{"3":{"action":"application","executable":"editor.exe","process":"editor"}}}""").Mappings["3"].LaunchAlways);
Check("Applications can resend file arguments on each press", Configuration.Parse("""{"mappings":{"3":{"action":"application","executable":"editor.exe","process":"editor","arguments":["config.json"],"launchAlways":true}}}""").Mappings["3"].LaunchAlways);
Reject("launchAlways must be boolean", """{"mappings":{"3":{"action":"application","executable":"editor.exe","process":"editor","launchAlways":"true"}}}""");
var area = new System.Drawing.Rectangle(-1001, -801, 1001, 801);
var halfLeft = Layouts.Bounds("left", area, default);
var halfRight = Layouts.Bounds("right", area, default);
Check("Odd-width halves meet without gaps or overlap", halfLeft.Right == halfRight.Left && halfLeft.Width + halfRight.Width == area.Width && halfRight.Right == area.Right);
var halfTop = Layouts.Bounds("top", area, default);
var halfBottom = Layouts.Bounds("bottom", area, default);
Check("Odd-height halves meet without gaps or overlap", halfTop.Bottom == halfBottom.Top && halfTop.Height + halfBottom.Height == area.Height && halfBottom.Bottom == area.Bottom);
var quarters = new[] { "top-left", "top-right", "bottom-left", "bottom-right" }.Select(l => Layouts.Bounds(l, area, default)).ToArray();
Check("Corners fill work area exactly", quarters.Sum(r => r.Width * r.Height) == area.Width * area.Height && quarters.All(area.Contains));
Check("Bottom-right respects negative origin and odd edges", quarters[3] == new System.Drawing.Rectangle(-501, -401, 501, 401));
Check("Preserve clamps oversized window to work area", Layouts.Bounds("preserve", area, new(2000, 2000)) == area);
Check("Identical bounds skip repositioning", Layouts.Matches(area, area));
Check("Moved window needs repositioning", !Layouts.Matches(area, new(area.X + 10, area.Y, area.Width, area.Height)));
foreach (string layout in Layouts.Names)
    Check($"Accept layout {layout}", Configuration.Parse("{\"mappings\":{\"4\":{\"action\":\"folder\",\"path\":\"C:/\",\"layout\":\"" + layout + "\"}}}").Mappings["4"].Layout == layout);
Reject("Unknown layout rejected", """{"mappings":{"4":{"action":"folder","path":"C:/","layout":"diagonal"}}}""");
Reject("Old size keyword rejected after rename", """{"mappings":{"4":{"action":"folder","path":"C:/","size":"left"}}}""");
var dedicated = new DedicatedWindows();
var firstWindow = new WindowCandidate(11, 101, 1001, 10);
var secondWindow = new WindowCandidate(22, 102, 1002, 20);
Check("Dedicated adopts sole existing window", dedicated.Select("7", [firstWindow]) == 11);
Check("Dedicated stays on adopted window despite newer focus", dedicated.Select("7", [firstWindow, secondWindow]) == 11);
Check("Closed dedicated window adopts remaining window", dedicated.Select("7", [secondWindow]) == 22);
var thirdWindow = new WindowCandidate(33, 103, 1003, 30);
var manual = new DedicatedWindows();
Check("Manual assignment chooses requested window", manual.Assign("7", firstWindow, [firstWindow, secondWindow]));
Check("Manual assignment remains sticky over MRU", manual.Select("7", [firstWindow, secondWindow]) == firstWindow.Handle);
Check("Reassignment switches without closing windows", manual.Assign("7", secondWindow, [firstWindow, secondWindow]) && manual.Select("7", [firstWindow, secondWindow]) == secondWindow.Handle);
Check("Closed or mismatched selection rejected", !manual.Assign("7", thirdWindow, [firstWindow, secondWindow]));
Check("Rejected assignment preserves current window", manual.Current("7", [firstWindow, secondWindow]) == secondWindow.Handle);
Check("Recycled process identity rejected", !manual.Assign("7", secondWindow, [secondWindow with { Started = 9999 }]));
var shortcuts = new Configuration { Mappings = new() { ["7"] = new Mapping { Action = "application", Selection = "dedicated" }, ["8"] = new Mapping() } };
Check("Ctrl dedicated captures assignment", ShortcutPolicy.Capture(7, true, true, shortcuts));
Check("Ctrl recent passes through", !ShortcutPolicy.Capture(8, true, true, shortcuts));
Check("Disabled Ctrl shortcut passes through", !ShortcutPolicy.Capture(7, true, false, shortcuts));
Check("Ctrl zero does not toggle", !ShortcutPolicy.Capture(0, true, true, shortcuts));
Check("Plain zero still enables while disabled", ShortcutPolicy.Capture(0, false, false, shortcuts));
Check("Num Lock on assignment passes through", new KeyPolicy().Handle(0x47, true, true, ShortcutPolicy.Capture(7, true, true, shortcuts)) == (false, false));
Check("Closed dedicated chooses most recently used replacement", dedicated.Select("7", [firstWindow, thirdWindow]) == 33);
Check("Adopted replacement remains dedicated", dedicated.Select("7", [firstWindow with { LastFocused = 99 }, thirdWindow]) == 33);
Check("No dedicated candidate requests launch", dedicated.Select("7", []) == 0);
Check("Newly launched window becomes dedicated", dedicated.Select("7", [secondWindow]) == 22);
Check("Recycled handle with another process is not treated as tracked", dedicated.Select("7", [secondWindow with { Pid = 104, Started = 1004 }, thirdWindow]) == 33);
Check("Fresh session adopts most recently used existing window", new DedicatedWindows().Select("7", [firstWindow, secondWindow]) == 22);
